def get_receipt(path: object, tx_id: object) -> dict:
    """Look up one previously merged finalized receipt in the index.

    ``path`` is the receipt index maintained by :func:`advance_receipts`
    and ``tx_id`` a caller-pinned 64-lowercase-hex transaction id.
    Success returns ``{"ok": True, "finalized", "item"}`` in that key
    order with ``finalized`` the index's closed ``{height, block_hash}``
    boundary and ``item`` the stored ``{receipt, proof}`` pair in its
    fixed contract key order. An existing index that does not know the
    id returns ``{"ok": False, "error": "not_found"}``; a bad path or
    ``tx_id`` shape is ``input``, an index failing its strict checks
    (shape, ordering, digest, or a stored item's recomputed tx_id,
    Ed25519 signature, confirmed status, receipt/proof binding or Merkle
    sibling replay) is ``state`` and a missing file or a read failure is
    ``io``. Nothing is raised and the file is never modified.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if not crypto.is_hex64(tx_id):
        return {"ok": False, "error": ERR_INPUT}

    lock = _checkpoint_lock(path)
    with lock:
        try:
            stored = _load_receipt_index(path)
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}
        except Exception:
            # Defensive: an unreadable-by-surprise index must report
            # rather than crash the caller.
            return {"ok": False, "error": ERR_STATE}
        if stored is None:
            return {"ok": False, "error": ERR_IO}
        for item in stored["items"]:
            if item["receipt"]["tx_id"] == tx_id:
                return {
                    "ok": True,
                    "finalized": {
                        key: stored["finalized"][key] for key in HEADER_ANCHOR_KEYS
                    },
                    "item": item,
                }
        return {"ok": False, "error": ERR_NOT_FOUND}

def _checkpoint_lock(path: str) -> threading.RLock:
    key = os.path.abspath(path)
    with _checkpoint_locks_guard:
        lock = _checkpoint_locks.get(key)
        if lock is None:
            lock = threading.RLock()
            _checkpoint_locks[key] = lock
        return lock


def _canonical_json_bytes(value: object) -> bytes:
    """Sorted-key, compact, unescaped-non-ASCII UTF-8 canonical JSON bytes."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def _checkpoint_state_hash(generation: int, anchor: dict, tip: dict, context: dict) -> str:
    """SHA-256 over the canonical JSON bytes of every field but state_hash."""
    body = {
        "generation": generation,
        "anchor": anchor,
        "tip": tip,
        "context": context,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _failed_advance(category: str) -> dict:
    return {"ok": False, "error": category}

def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


